insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a1', 'Regional Blocs Resume Trade Talks as Tariff Deadline Looms', 'Negotiators from three continents return to the table this week, with agricultural tariffs and digital-services rules the last unresolved sticking points.', 'politics', 'M. Okafor', 'Brussels', '2026-07-13T09:00:00Z', 'https://picsum.photos/seed/tradetalks/1200/800', true, true, true, 'news', '["Trade envoys reconvened in Brussels on Monday for a fourth round of talks aimed at averting a tariff snapback that would hit an estimated $80 billion in annual cross-border trade.","The talks, which stalled in the spring over disagreements on data-localization rules, have taken on new urgency as a self-imposed August deadline approaches. Officials on both sides described the mood as ''cautiously constructive'' but declined to characterize a deal as imminent.","At the center of the dispute is a proposed carve-out for agricultural subsidies, which one bloc argues distorts competition and the other frames as essential food-security policy. A senior negotiator said a compromise text is circulating but has not been formally tabled.","Analysts note that failure to reach an agreement would not trigger an immediate tariff increase, but would restart a 90-day countdown clause written into the expiring framework. Markets have so far shown limited reaction, though currency traders are watching the talks closely.","A further session is expected before the end of the month, with mid-level technical staff continuing work on the text in the interim."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a2', 'Ceasefire Monitors Report Reduced Shelling Along Contact Line', 'International observers say artillery exchanges have dropped by roughly a third over the past ten days, though both sides dispute the underlying cause.', 'world', 'T. Ivanenko', 'Kyiv', '2026-07-12T14:20:00Z', 'https://picsum.photos/seed/frontline/1200/800', false, true, false, 'news', '["Monitors stationed along the contact line reported a marked decline in artillery activity over the past ten days, according to a summary released Sunday.","The reduction has not been formally attributed to any agreement, and officials from both sides offered competing explanations, ranging from weather disruption to a deliberate operational pause.","Humanitarian groups operating in the region cautioned against reading too much into the lull, noting that similar quiet periods in the past have preceded renewed offensives rather than de-escalation.","Diplomats say back-channel discussions continue, though no formal talks have been scheduled."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a3', 'Central Bank Holds Rates, Signals Data-Dependent Path Ahead', 'Policymakers kept the benchmark rate unchanged for a third straight meeting, citing sticky services inflation and a resilient labor market.', 'world', 'R. Chen', 'Washington, D.C.', '2026-07-11T18:00:00Z', 'https://picsum.photos/seed/centralbank/1200/800', false, false, false, 'news', '["The central bank left its benchmark interest rate unchanged Wednesday, extending a pause that began in the spring as officials weigh persistent services inflation against signs of cooling in goods prices.","In prepared remarks, the chair described the current stance as ''appropriately restrictive'' while declining to rule out further action later in the year.","Futures markets modestly trimmed expectations for a rate cut before year-end, pushing implied odds below 40 percent.","The decision was not unanimous; two committee members reportedly favored a quarter-point cut, according to people familiar with the discussion."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a4', 'Coalition Government Survives Confidence Vote by Narrow Margin', 'A minority coalition cleared its first major parliamentary test, but the seven-vote margin exposes fragile footing ahead of a contentious budget debate.', 'politics', 'H. Larsen', 'London', '2026-07-10T20:15:00Z', 'https://picsum.photos/seed/parliament/1200/800', false, true, false, 'news', '["The governing coalition survived a confidence motion Thursday evening by a margin of seven votes, a result that steadies the government in the short term but underscores how thin its working majority has become.","The vote was called by the opposition after weeks of friction over proposed changes to energy subsidies. Several backbenchers from the ruling coalition abstained rather than vote against their own government, a sign of internal strain that officials played down.","Attention now turns to next month''s budget vote, widely seen as a tougher test given the scale of proposed spending cuts.","Political analysts say the government''s position remains workable but leaves little room for further defections."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a5', 'Chipmakers Warn Export Controls Could Reshape Supply Chains for a Decade', 'Industry executives say new licensing rules on advanced semiconductor equipment are already prompting firms to duplicate production lines across jurisdictions.', 'analysis', 'J. Park', 'Tokyo', '2026-07-09T11:00:00Z', 'https://picsum.photos/seed/semiconductors/1200/800', false, false, false, 'analysis', '["Executives across the semiconductor industry say a tightening web of export controls on advanced chipmaking equipment is forcing a level of supply-chain duplication not seen since the industry began globalizing in the 1990s.","Firms that once ran a single advanced fabrication line for a global customer base are now weighing parallel investments to serve markets subject to different licensing regimes — an expensive hedge against a policy environment executives describe as unpredictable.","The shift carries real costs: analysts estimate duplicated capacity could add tens of billions of dollars in capital expenditure industry-wide over the next five years, costs likely to be passed on to consumers of everything from phones to cars.","Some governments are offering subsidies to offset the burden, but the patchwork of incentives is itself becoming a source of friction between allied economies.","The longer-term effect, several executives argued, may be a less efficient but more resilient global chip supply — a trade-off many now consider unavoidable."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a6', 'Water-Sharing Dispute Resurfaces as Drought Grips River Basin', 'A three-decade-old agreement is under renewed strain as upstream and downstream states clash over falling reservoir levels.', 'world', 'A. Mensah', 'Nairobi', '2026-07-08T08:30:00Z', 'https://picsum.photos/seed/riverbasin/1200/800', false, false, false, 'news', '["A long-standing water-sharing agreement governing one of the region''s major river basins is facing its most serious test in years, as a prolonged drought pushes reservoir levels to their lowest point in three decades.","Downstream farmers say reduced releases from upstream dams threaten this season''s harvest, while upstream officials point to their own shrinking hydropower capacity as justification for the cuts.","Regional bodies have called for emergency talks, though previous attempts to revise the allocation formula have taken years to negotiate.","Climate researchers say the basin''s rainfall variability is likely to increase, meaning disputes of this kind may become more frequent rather than less."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a7', 'The Quiet Return of Industrial Policy', 'Governments that spent forty years dismantling subsidies and tariffs are rebuilding them — and calling it something else.', 'beyond', 'S. Whitfield', 'Washington, D.C.', '2026-07-07T10:00:00Z', 'https://picsum.photos/seed/industrypolicy/1200/800', false, false, false, 'analysis', '["For most of the past two generations, industrial policy was something governments in wealthy democracies mostly disavowed in public even when they practiced it in private. Picking winners was for planned economies; markets, the thinking went, would allocate capital better than ministries could.","That consensus has quietly collapsed. Subsidy programs for semiconductors, batteries, and critical minerals now run into the hundreds of billions of dollars across multiple economies, often justified not in the language of industrial strategy but of national security or supply-chain resilience.","The relabeling matters. Framing subsidies as security measures makes them easier to defend politically and harder to challenge under trade rules built for an earlier era. It also makes them harder to unwind — a security rationale does not expire the way an infant-industry argument eventually should.","What''s easy to miss in the daily headlines about individual deals is the cumulative shift: a return to a world where governments treat the location of production, not just its price, as a strategic variable. That is a genuine break from the last four decades, and it will outlast any single administration or election cycle.","The deeper question is not whether this approach works for any one factory or one country, but what happens when every major economy plays the same game at once — a version of industrial policy with no clear equilibrium, only escalation."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a8', 'Why Ceasefires Fail More Often Than They Hold', 'A look at the pattern behind fragile truces — and what separates the rare ones that stick from the many that don''t.', 'beyond', 'T. Ivanenko', 'Kyiv', '2026-07-06T09:00:00Z', 'https://picsum.photos/seed/ceasefirepattern/1200/800', false, false, false, 'analysis', '["Every ceasefire is announced as if it might be the last one needed. Most are not. Research on armed conflicts since 1990 suggests a majority of ceasefires break down within a year, and a significant share collapse within the first month.","The pattern has less to do with the sincerity of either side and more to do with structure. Ceasefires negotiated without a credible monitoring mechanism, without a political track running alongside the military one, and without a third party willing to impose costs for violations tend to fail at far higher rates than those with all three.","This is worth remembering every time a truce is announced to relief and cautious celebration: the announcement is the easy part. What determines whether it holds is usually decided in the unglamorous details that rarely make headlines — verification protocols, prisoner exchange mechanics, and who exactly answers for the first violation.","None of this means ceasefires are not worth pursuing. It means the right question, on the day one is announced, is rarely ''will it hold'' in the abstract, but ''does this one have the scaffolding that history suggests it needs.''"]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a9', 'The Migration Numbers Nobody Is Debating — Because Nobody Agrees on Them', 'Three governments, three wildly different estimates of the same border crossings. The discrepancy is itself the story.', 'opinion', 'S. Whitfield', 'Brussels', '2026-07-05T12:00:00Z', 'https://picsum.photos/seed/migrationdata/1200/800', false, false, false, 'opinion', '["Ask three governments how many people crossed a shared border last month and you will, with some regularity, get three different answers — not off by a rounding error, but by a factor of two or more. This is not usually fraud. It is method: one country counts entries, another counts unique individuals, a third counts only those who file a claim.","I''ve spent enough time comparing these figures to conclude that the disagreement itself is more informative than any single number. A government that counts generously is usually building a case for more resources. One that counts conservatively is usually managing a domestic political narrative. Neither is lying, exactly, but neither is neutral either.","My own view, for what it''s worth, is that the public debate would be healthier if commentators spent less energy citing whichever number flatters their argument and more energy asking which counting method produced it. The politics of migration are contentious enough without also fighting over arithmetic that a shared methodology could resolve in an afternoon.","This is a solvable problem. That it remains unsolved after years of political attention tells you something about how useful the ambiguity is to everyone involved."]'::jsonb) on conflict (id) do nothing;
insert into articles (id, title, dek, category, author, dateline, published_at, image, breaking, trending, featured, type, body) values ('a10', 'Opinion: The Summit Communiqué Nobody Will Read Still Matters', 'Diplomatic language is often mocked as empty. It isn''t. The wording is frequently the entire negotiation.', 'opinion', 'M. Okafor', 'Brussels', '2026-07-04T15:00:00Z', 'https://picsum.photos/seed/communique/1200/800', false, false, false, 'opinion', '["Summit communiqués are easy to mock: pages of hedged, passive-voice language that most readers, reasonably, skip entirely. I used to skip them too, until I sat through enough closed-door drafting sessions to understand that the hedging is not a failure of the process. It is the process.","A single verb — ''urges'' versus ''calls on,'' ''notes'' versus ''welcomes'' — can be the product of six hours of argument between delegations that agree on almost nothing else. The document that results is deliberately boring because boring is what consensus among rivals looks like on paper.","I''d argue the right way to read a communiqué is not as a statement of intent but as a snapshot of exactly how much disagreement a group of governments were willing to paper over in public. Read that way, the document that seems to say nothing is often the most honest account of the summit that exists.","None of this is an argument that communiqués deserve more front-page attention. It''s an argument for taking them more seriously exactly where they currently get the least: in the fine print, where the actual negotiation lives."]'::jsonb) on conflict (id) do nothing;
